(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["microbiology-exam-1-transmission-of-microorganisms-quiz-version-2"]={"title":"Transmission of Microorganisms — Quiz 2","category":"Microbiology","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"Where did the idea for anti-fouling surface coatings originate?","choices":["Textile dyeing","Marine ship coatings","Food packaging","Aircraft manufacture"],"answer":1,"exp":"Correct — copper, arsenic, mercury and tin compounds since the 1960s. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 40"},{"q":"What are the reservoirs of influenza?","choices":["Mammals by bite","Fruit bats","Contaminated soil","Birds and pigs"],"answer":3,"exp":"Correct, transmitted by respiratory droplet and contact. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"What two conditions must chemical disinfectants meet to work?","choices":["Use within one hour of opening","Concentration and contact time","A warm room and bright light","Application by a doctor"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 39"},{"q":"What do COMPETENT cells do in transformation?","choices":["Take up DNA fragments from their environment","Inject DNA into neighbouring cells","Package DNA into viral particles","Excise resistance genes and destroy them"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 45"},{"q":"What did Lister use in the 1860s?","choices":["Carbolic acid","Chlorine solution","Alcohol hand gel","Silver nitrate"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 37"},{"q":"Why are persistent pathogens on fomites particularly dangerous?","choices":["They only survive minutes","They are always drug-sensitive","They look like clean surfaces","They glow under ultraviolet light"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 39"},{"q":"Which four properties should a hospital surface coating have?","choices":["Reflective, rigid, heavy and opaque","Porous, flexible, warm and light","Nontoxic, cost effective, stable and durable","Colourful, cheap, disposable and soft"],"answer":2,"exp":"Correct, and commercially available. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 40"},{"q":"What is the difference between an ANTI-FOULING and an ANTIMICROBIAL coating?","choices":["Anti-fouling is used only on skin","Anti-fouling prevents attachment; antimicrobial kills","They are two words for the same thing","Anti-fouling kills; antimicrobial prevents attachment"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 40"},{"q":"Which organisms were found at counts above ten thousand per millilitre?","choices":["Candida and Aspergillus","Mycobacterium tuberculosis","Klebsiella pneumoniae, Pseudomonas aeruginosa and Acinetobacter","Staphylococcus aureus, Streptococcus pyogenes and Enterococcus"],"answer":2,"exp":"Correct — gram-negative organisms. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 43"},{"q":"How are hospital-acquired infections PRIMARILY transmitted?","choices":["Directly, human to human","Indirectly, by fomite contact","By insect vectors","Through contaminated soil"],"answer":0,"exp":"Correct — fomite contact is the secondary route. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 37"},{"q":"Which occupation is named as carrying a risk of zoonotic transmission?","choices":["Accountancy","Software engineering","Air traffic control","Veterinary medicine"],"answer":3,"exp":"Correct — with farm work, landscaping, zookeeping and meat processing. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 6"},{"q":"What does VERTICAL transmission mean?","choices":["From a surface to a person","From an animal to a person","Mother to child","Between two adults by sexual contact"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 17"},{"q":"From which hospital wards did the most heavily contaminated samples come?","choices":["Outpatient clinics only","Administrative offices","Maternity and neonatology","Radiology and pathology"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 43"},{"q":"Why must a room be vacant before using ozone or high-concentration hydrogen peroxide?","choices":["To reduce harm to humans","To let the surfaces dry first","To avoid disturbing the patient's sleep","To allow the temperature to drop"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 39"},{"q":"Why does the viral share of infections matter for treatment?","choices":["Viral disease cannot be cured with antibiotics","Viruses always respond to antibiotics","Viral infections never require treatment","Viruses cannot be transmitted by fomites"],"answer":0,"exp":"Correct — prevention relies on vaccines and antivirals. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 32"},{"q":"How many published studies did the keyboard systematic review analyse?","choices":["Seventy-five","Fifteen","Two hundred","Five"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 31"},{"q":"What is a zoonosis?","choices":["An infection spread only by insects","An infection acquired only from soil","An animal infection that can spread to humans","An infection that only ever affects animals"],"answer":2,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 7"},{"q":"What does the abbreviation HAI stand for?","choices":["Host-adapted infection","Highly aggressive infection","Hygiene-associated incident","Hospital-acquired infection"],"answer":3,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 19"},{"q":"Which reservoir is shared by Ebola, Marburg and Nipah viruses?","choices":["Birds","Rodents","Domestic cattle","Fruit bats"],"answer":3,"exp":"Correct — with small primates for Ebola. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"Typhoid Mary is given as the classic example of which reservoir?","choices":["A zoonotic reservoir","An active carrier","A passive carrier","A non-living reservoir"],"answer":1,"exp":"Correct — Mary Mallon carried Salmonella typhi without symptoms. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 5"},{"q":"How is Ebola transmitted?","choices":["Body fluids, and human to human","Respiratory droplet only","Bite and saliva","Contaminated soil"],"answer":0,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 8"},{"q":"Which non-living reservoir is defined as a surface or object?","choices":["Soil","Water","Air","Fomites"],"answer":3,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 4"},{"q":"Which item appears on the Kanamori list of patient-care fomites?","choices":["The staff rota","The ultrasound probe and its gel","The patient's medication chart","The ward noticeboard"],"answer":1,"exp":"Correct — with stethoscopes, thermometers and blood pressure monitors. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 34"},{"q":"Outside a clinical setting, where else is a fomite-filled room found?","choices":["A hotel room or aeroplane","Only in intensive care","Only in operating theatres","Only in laboratories"],"answer":0,"exp":"Correct — a public restroom too. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 24"},{"q":"Which everyday hospital items are named among the electronic fomites?","choices":["Scalpels and syringes","Bed rails and gurneys","Mops and brooms","Telephones and keyboards"],"answer":3,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 23"},{"q":"Which of these is listed as a clinical fomite?","choices":["An airborne droplet","A mosquito","Stethoscopes","The patient's own skin flora"],"answer":2,"exp":"Correct — with neckties, stuffed animals, greeting cards and flowers. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 23"},{"q":"Who must be educated about cleaning and disinfection policy?","choices":["Only infection control staff","All staff, without exception","Only doctors","Only nurses"],"answer":1,"exp":"Correct. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 35"},{"q":"Why can a zoonotic infection not be completely eliminated?","choices":["No vaccines exist for zoonoses","Antibiotics never work against them","They are always fatal","The animal reservoir persists"],"answer":3,"exp":"Correct — and it is harder still with multiple reservoirs. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 7"},{"q":"What did the birthday-cake study find about blowing out candles?","choices":["Fewer bacteria than the control","About fifteen times more bacteria","No measurable difference","About twice as many bacteria"],"answer":1,"exp":"Correct, compared with the no-blow control. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 29"},{"q":"What did the birthday-cake authors NOT do?","choices":["Publish their results","Identify the bacteria","Use a control condition","Report colony counts"],"answer":1,"exp":"Correct — the organisms were counted but never identified. — PAJ5200.Transmission_of_microbes-2.pptx, Slide 29"}]};
